-- migration_014_new_questions_sept2026c.sql
-- Batch 3 of new questions from "Questions to add.pdf": median nerve actions
-- (Anatomy), non-conventional properties of local anaesthetics, oral
-- bioavailability, intra-articular corticosteroid injection, best evidence for
-- facet joint pain (SBA), CRPS associations, HPA axis suppression after
-- intra-articular triamcinolone, low back pain epidemiology, S1 nerve root
-- compression (Anatomy), and polymyalgia rheumatica.
--
-- Several carry knowledge boxes with zoomable reference tables/figures
-- (median nerve course & innervation, LA classification, steroid mechanism-of-
-- action diagram, corticosteroid comparison table, lower-limb dermatome map,
-- CRPS and PMR summaries). Two questions embed an orange NICE NG59 button.
-- Assets added: images/steroids-mechanism-of-action.svg,
-- images/dermatomes-lower-limb.png.
--
-- Safe to run directly in the Supabase SQL Editor. Idempotent (on conflict do
-- nothing) so it can be re-run harmlessly. No new categories are introduced.

insert into questions (id, type, data, status) values ('q_mtf_median_nerve_actions_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":81,"stem":"Which of the following actions are mediated by the median nerve?","choices":["Adduction of the index finger","Abduction of the thumb","Flexion of the thumb","Flexion of the ring finger","Opposition of the thumb"],"correct":[false,true,true,false,true],"explanation":"<p>The median nerve supplies most of the forearm flexor compartment (except flexor carpi ulnaris and the medial half of flexor digitorum profundus, both ulnar) and the thenar and lateral lumbrical muscles in the hand, remembered by the \"LOAF\" mnemonic &mdash; Lateral two lumbricals, Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; Adduction of the index finger &mdash; and finger adduction generally &mdash; is performed by the palmar interossei, which are innervated by the ulnar nerve, not the median nerve.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; Abductor pollicis brevis, part of the thenar group, is innervated by the median nerve and abducts the thumb (moving it anteriorly away from the palm). This is the muscle classically tested in median nerve examination &mdash; thumb abduction against resistance.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Thumb flexion is produced by flexor pollicis brevis (superficial head, median-innervated) and flexor pollicis longus (median nerve via its anterior interosseous branch), making thumb flexion predominantly a median nerve function.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> &mdash; Flexion of the ring finger at the DIP joint is produced by the medial half of flexor digitorum profundus, which is supplied by the <strong>ulnar</strong> nerve. The median nerve, via the anterior interosseous branch, supplies only the lateral half of profundus (index and middle fingers). Flexor digitorum superficialis is entirely median-innervated and does flex all four fingers at the PIP joints, but profundus-mediated flexion of the ring finger is an ulnar function.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Opposition of the thumb is performed by opponens pollicis, part of the thenar group and innervated by the median nerve. Loss of opposition is a classic finding in median nerve palsy (\"ape hand\" deformity).</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Median Nerve</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Origin</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Formed from the lateral cord (C6, C7) and the medial cord (C8, T1) of the brachial plexus.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Course (proximal &rarr; distal)</div><table style=\"margin:0\"><tr><th>Step</th></tr><tr><td>Descends through the arm alongside the brachial artery &mdash; initially lateral, then crossing medially at about mid-humerus level</td></tr><tr><td>Passes through the antecubital fossa medial to the brachial artery, deep to the bicipital aponeurosis</td></tr><tr><td>Enters the forearm between the two heads of pronator teres</td></tr><tr><td>Runs between flexor digitorum superficialis and flexor digitorum profundus in the forearm</td></tr><tr><td>Gives off the anterior interosseous nerve in the proximal forearm</td></tr><tr><td>Emerges at the wrist between the flexor carpi radialis and palmaris longus tendons</td></tr><tr><td>Passes through the carpal tunnel (deep to the flexor retinaculum) to enter the hand</td></tr><tr><td>Gives off the recurrent (motor) branch to the thenar muscles just distal to the carpal tunnel</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Motor innervation</div><table style=\"margin:0\"><tr><th>Level</th><th>Muscles supplied</th></tr><tr><td>Forearm &mdash; main trunk</td><td>Pronator teres; flexor carpi radialis; palmaris longus; flexor digitorum superficialis (all four digits)</td></tr><tr><td>Anterior interosseous nerve (AIN) &mdash; pure motor branch</td><td>Flexor pollicis longus; flexor digitorum profundus (lateral half &mdash; index and middle fingers); pronator quadratus</td></tr><tr><td>Hand &mdash; \"LOAF\" muscles (recurrent branch + lateral two lumbricals)</td><td>Lateral two lumbricals (index and middle finger MCP flexion / IP extension); opponens pollicis (thumb opposition); abductor pollicis brevis (thumb abduction); flexor pollicis brevis, superficial head (thumb flexion)</td></tr></table><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Adductor pollicis and the deep head of flexor pollicis brevis are ulnar-innervated; all palmar and dorsal interossei (finger abduction / adduction) are ulnar.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Sensory innervation</div><table style=\"margin:0\"><tr><th>Territory</th></tr><tr><td>Palmar aspect of the lateral 3&frac12; digits (thumb, index, middle, and lateral half of the ring finger) and the corresponding palm</td></tr><tr><td>Dorsal aspect of the fingertips (distal phalanges) of the same digits</td></tr><tr><td>The palmar cutaneous branch supplies the skin of the lateral palm; it arises proximal to the carpal tunnel, which is why palm sensation is often spared in carpal tunnel syndrome</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinically important lesions</div><table style=\"margin:0\"><tr><th>Lesion site</th><th>Cause</th><th>Key features</th></tr><tr><td>Carpal tunnel (distal)</td><td>Carpal tunnel syndrome</td><td>Sensory loss over the lateral 3&frac12; digits (palm spared), thenar wasting, weak thumb abduction / opposition</td></tr><tr><td>Supracondylar fracture / elbow</td><td>Trauma</td><td>Loss of pronation, weak wrist flexion, \"hand of benediction\" on attempted fist, sensory loss as above</td></tr><tr><td>Anterior interosseous nerve (isolated)</td><td>Compression / trauma</td><td>Pure motor: weak pincer grip (FPL + FDP to index) &mdash; positive \"OK sign\" test (cannot form a circle); no sensory loss</td></tr><tr><td>Pronator teres syndrome</td><td>Compression at pronator teres</td><td>Similar to a proximal median lesion but with forearm pain, and pronator teres itself is spared</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Associated signs</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Hand of benediction:</strong> seen on trying to make a fist with a proximal median nerve lesion &mdash; the index and middle fingers fail to flex (FDS and lateral FDP affected) while the ring and little fingers flex normally (ulnar-innervated medial FDP).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>Ape hand / simian hand:</strong> seen with long-standing median nerve palsy &mdash; thenar wasting with loss of opposition and abduction leaves the thumb lying flattened in the plane of the palm.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_local_anaesthetic_properties_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":82,"stem":"Regarding the properties of local anaesthetics beyond nerve conduction blockade:","choices":["Antiviral properties","Antibacterial properties","Anti-metastatic properties","Anti-inflammatory properties","Antioxidant properties"],"correct":[true,true,true,true,true],"explanation":"<p>Beyond their primary sodium-channel-blocking mechanism producing nerve conduction blockade, local anaesthetics have several recognised \"non-conventional\" pharmacological properties of increasing clinical and research interest, particularly in perioperative and cancer medicine.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; Local anaesthetics show antiviral activity in vitro, thought to relate to membrane-stabilising effects interfering with viral entry and replication, though the clinical significance in practice is limited.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; Local anaesthetics have antibacterial properties against a range of organisms, attributed to disruption of bacterial cell membranes; this underlies interest in their use as an adjunct to prevent catheter-related infection.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Local anaesthetics have shown anti-metastatic / anti-cancer properties in preclinical studies, potentially via inhibition of cancer cell migration and invasion (voltage-gated sodium channels are expressed by some cancer cell types and implicated in metastatic potential).</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Local anaesthetics have anti-inflammatory effects, including inhibition of neutrophil function (chemotaxis, degranulation, reactive oxygen species release) and modulation of inflammatory cytokine release &mdash; contributing to the benefits seen with techniques such as intravenous lidocaine infusion in enhanced recovery protocols.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Local anaesthetics have demonstrated antioxidant properties, including scavenging of reactive oxygen species, contributing to some of the proposed organ-protective effects seen in experimental models.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Local anaesthetics</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Local anaesthetics (LAs) are weak bases that reversibly block voltage-gated sodium channels from the intracellular side of the neuronal membrane, preventing sodium influx, action potential propagation, and nerve conduction.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">To reach this intracellular binding site, the uncharged (lipid-soluble) form must first cross the lipid membrane; a proportion then re-ionises intracellularly to the charged form, which is the active species at the sodium channel.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification</div><table style=\"margin:0\"><tr><th>Class</th><th>Examples</th><th>Notes</th></tr><tr><td>Esters</td><td>Cocaine, procaine, tetracaine, chloroprocaine</td><td>Metabolised by plasma cholinesterase; higher allergy potential (PABA metabolite)</td></tr><tr><td>Amides</td><td>Lidocaine, bupivacaine, levobupivacaine, ropivacaine, prilocaine</td><td>Metabolised hepatically; recognised by two \"i\"s in the name before \"-caine\"</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Factors affecting clinical effect</div><table style=\"margin:0\"><tr><th>Factor</th><th>Effect</th></tr><tr><td>pKa (onset)</td><td>pKa is the pH at which 50% of the drug is ionised and 50% unionised. The unionised (lipophilic) form crosses the membrane, so a lower pKa (closer to pH 7.4) gives more unionised drug and a faster onset (e.g. lidocaine, pKa ~7.9, is faster than bupivacaine, ~8.1). In infected / acidic tissue more drug stays ionised, reducing membrane penetration and LA efficacy.</td></tr><tr><td>Lipid solubility (potency)</td><td>Higher lipid solubility &rarr; easier passage through the lipid-rich neuronal membrane &rarr; greater potency.</td></tr><tr><td>Protein binding (duration)</td><td>LAs bind mainly to alpha-1 acid glycoprotein (and albumin). Higher protein binding means the drug stays bound at the sodium channel longer &rarr; longer duration (bupivacaine ~95% bound lasts far longer than lidocaine ~65%).</td></tr><tr><td>Dose / concentration / volume</td><td>A higher total dose increases the concentration gradient driving diffusion into the nerve, affecting onset speed and block density / duration.</td></tr><tr><td>Vasoactivity</td><td>Most LAs (except cocaine, which is vasoconstrictive) cause vasodilation, increasing systemic absorption and shortening local duration. Added adrenaline counteracts this &mdash; prolonging the block and lowering peak plasma concentration by reducing vascular uptake.</td></tr><tr><td>Site of injection</td><td>Highly vascular sites (e.g. intercostal block) &rarr; faster systemic absorption, shorter duration, higher plasma levels. Poorly vascular sites (e.g. subcutaneous) &rarr; slower absorption, longer local duration.</td></tr><tr><td>Fibre type / diameter</td><td>Smaller, unmyelinated C fibres (pain, temperature) are blocked before larger, myelinated fibres (A&beta; touch, motor) &mdash; explaining why sensory block precedes motor block.</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_oral_bioavailability_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":83,"stem":"Which of the following affect the oral bioavailability of a drug?","choices":["Intestinal pH","Gastric emptying rate","Drug formulation / preparation","First-pass hepatic metabolism","Physicochemical properties of the drug (e.g. lipid solubility, molecular size)"],"correct":[true,true,true,true,true],"explanation":"<p>Oral bioavailability describes the proportion of an administered dose that reaches the systemic circulation unchanged.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; Intestinal (and gastric) pH sets the degree of ionisation of weakly acidic or basic drugs, which in turn determines the proportion of unionised, lipid-soluble drug available for passive diffusion across the gut mucosa &mdash; altering both the rate and the extent of absorption.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; Gastric emptying rate determines how quickly a drug reaches the small intestine, the main site of absorption for most oral drugs; delayed emptying (opioids, illness, food) slows absorption and delays the peak plasma concentration.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Formulation (tablet vs liquid, immediate- vs modified-release, particle size, excipients) markedly affects dissolution and subsequent absorption, and different formulations of the same drug can have very different bioavailability.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; First-pass hepatic metabolism &mdash; passage of absorbed drug via the portal vein through the liver before it reaches the systemic circulation &mdash; is a major determinant of oral bioavailability; drugs with high first-pass metabolism (e.g. morphine, propranolol, GTN) have markedly reduced oral bioavailability compared with parenteral administration.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; The drug''s own physicochemical properties &mdash; lipid solubility, molecular size, degree of ionisation (pKa relative to gut pH), and stability in gastric acid &mdash; determine how readily it crosses the gut mucosa and survives the gastrointestinal environment, directly influencing absorption and bioavailability.</p>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_intraarticular_corticosteroid_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":84,"stem":"Regarding intra-articular corticosteroid injection:","choices":["Improves the viscoelastic properties of synovial fluid","Causes angiogenesis and cellular proliferation","Suppresses TNF-alpha","Produces an anti-inflammatory effect","Acts by inhibiting phospholipase A2"],"correct":[true,false,true,true,true],"explanation":"<p>Intra-articular corticosteroids produce a potent local anti-inflammatory effect by suppressing several components of the inflammatory cascade, acting higher in the arachidonic acid pathway than NSAIDs.</p>\n<p style=\"margin-top:12px\"><strong>A. TRUE</strong> &mdash; Corticosteroids can improve the viscoelastic properties of synovial fluid, partly by reducing the inflammatory breakdown of hyaluronic acid within the joint, contributing to improved joint mobility and reduced friction.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; Corticosteroids <strong>inhibit</strong> (rather than cause) angiogenesis and cellular proliferation, as part of their broader anti-inflammatory and immunosuppressive action, suppressing the proliferative and vascular components of the inflammatory response. This is also the basis for concern about impaired tissue healing and cartilage effects with repeated injection.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Corticosteroids suppress pro-inflammatory cytokines including TNF-alpha (along with IL-1 and IL-6), mainly via genomic mechanisms that reduce transcription of inflammatory mediator genes.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; The overall clinical effect of an intra-articular corticosteroid is a potent local anti-inflammatory action, reducing synovial inflammation, joint swelling, and associated pain.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Corticosteroids act by inhibiting phospholipase A2, preventing release of arachidonic acid from membrane phospholipids and thereby reducing downstream production of both prostaglandins (via COX) and leukotrienes (via lipoxygenase) &mdash; a broader anti-inflammatory action than NSAIDs, which block only the COX pathway.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Steroids mechanism of action</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Corticosteroids inhibit phospholipase A2 (via induction of lipocortin / annexin-1), blocking conversion of membrane phospholipid to arachidonic acid. Because this step sits upstream of the branch point, both the cyclo-oxygenase and the lipoxygenase arms are suppressed &mdash; reducing prostaglandins, leukotrienes, and other inflammatory mediators. NSAIDs act lower down, inhibiting only cyclo-oxygenase.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"text-align:center\"><img src=\"images/steroids-mechanism-of-action.svg\" alt=\"Steroids mechanism of action flow diagram: corticosteroids inhibit phospholipase A2 (phospholipid to arachidonic acid), while NSAIDs inhibit cyclo-oxygenase (arachidonic acid to prostaglandins); the lipoxygenase arm leads to leukotrienes and other inflammatory mediators\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_facet_joint_rf_evidence_001', 'SBA', '{"dateAdded":"2026-09-06","rotationIndex":85,"question":"Which of the following has the best evidence base for the treatment of facet joint pain?","choices":["Laser treatment of the facet joint","Cryoneurolysis","Percutaneous thermal radiofrequency (RF) denervation","Endoscopic treatment","Intra-articular facet joint steroid injection"],"correct":2,"explanation":"<p>Facet (zygapophyseal) joint pain is a common cause of axial spinal pain. Of the interventional options, percutaneous thermal radiofrequency denervation of the medial branches has the strongest supporting evidence, performed after a positive diagnostic medial branch block.</p>\n<p style=\"margin-top:12px\"><strong>A. Incorrect.</strong> Laser treatment of the facet joint lacks an established evidence base and is not supported by controlled trial data for this indication.</p>\n<p style=\"margin-top:8px\"><strong>B. Incorrect.</strong> Cryoneurolysis has a recognised evidence base (case series and comparative studies) but is generally shorter-lasting and less robustly supported than thermal radiofrequency, making it a reasonable alternative rather than the best-evidenced option.</p>\n<p style=\"margin-top:8px\"><strong>C. Correct.</strong> Thermal radiofrequency denervation has the best evidence base of the options listed, supported by multiple randomised controlled trials.</p>\n<p style=\"margin-top:8px\"><strong>D. Incorrect.</strong> Endoscopic treatment lacks an established evidence base for facet joint pain and is not part of standard evidence-based interventional pathways for this condition.</p>\n<p style=\"margin-top:8px\"><strong>E. Incorrect.</strong> Intra-articular facet joint steroid injection has mixed and comparatively weaker trial evidence, with a risk of intra-articular damage on repeated injection.</p>\n<div style=\"margin-top:18px\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ng59'',''NICE NG59 &mdash; Low Back Pain &amp; Sciatica'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE NG59 &mdash; Low Back Pain &amp; Sciatica\n</button></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_crps_associations_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":86,"stem":"Complex regional pain syndrome (CRPS) is associated with:","choices":["Asthma","Scleroderma","Hyperpigmentation","Oedema of the affected limb","Osteopenia"],"correct":[false,false,true,true,true],"explanation":"<p>CRPS is a chronic pain condition characterised by pain disproportionate to an inciting injury, accompanied by autonomic, sensory, motor, and trophic changes in the affected limb, reflecting dysregulation of both peripheral and central pain and autonomic pathways.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; Although both may share inflammatory and neurogenic pathways, asthma is not a recognised association of CRPS.</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; Scleroderma is a distinct autoimmune connective tissue disease causing skin fibrosis and is not a recognised association of CRPS. Both can cause skin and vascular changes, but they are separate entities with different pathophysiology (autoimmune fibrosis versus neuroinflammatory / autonomic dysregulation).</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Skin colour changes, including hyperpigmentation (as well as hypopigmentation, mottling, or cyanotic discolouration), are recognised trophic / autonomic features of CRPS, reflecting abnormal vasomotor and sudomotor regulation in the affected limb.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Oedema of the affected limb is one of the classic diagnostic features of CRPS (part of the Budapest criteria), reflecting vasomotor and sudomotor dysregulation with increased vascular permeability.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Osteopenia (patchy bone demineralisation) is a recognised trophic change in CRPS, classically seen as patchy osteopenia on plain X-ray and detected earlier and more sensitively on triple-phase bone scan, reflecting disuse and neurogenic inflammatory effects on bone metabolism in the affected limb.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Complex Regional Pain Syndrome</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">CRPS is a clinical disorder characterised by severe, continuous pain in the affected extremity, accompanied by sensory, vasomotor, sudomotor / oedema, and motor / trophic changes. The pain is regionally restricted (not confined to a single dermatome) and disproportionate to the inciting event.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">It typically follows trauma, surgery, or immobilisation, though it sometimes occurs with no identifiable trigger.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Incidence: approximately 5&ndash;26 per 100,000 person-years.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Types</div><table style=\"margin:0\"><tr><th>Type</th><th>Detail</th></tr><tr><td>CRPS Type I (previously \"reflex sympathetic dystrophy\")</td><td>No identifiable nerve injury &mdash; the majority of cases</td></tr><tr><td>CRPS Type II (previously \"causalgia\")</td><td>Occurs after a confirmed peripheral nerve injury</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria (Budapest criteria)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Requires continuing pain disproportionate to the inciting event, plus at least one symptom in 3 of 4 categories AND at least one sign in 2 of 4 categories at the time of assessment, with no other diagnosis better explaining the findings.</p><table style=\"margin:0\"><tr><th>Category</th><th>Symptoms / signs</th></tr><tr><td>Sensory</td><td>Hyperalgesia, allodynia</td></tr><tr><td>Vasomotor</td><td>Temperature asymmetry; skin colour changes / asymmetry (mottling, hyperpigmentation)</td></tr><tr><td>Sudomotor / oedema</td><td>Oedema; sweating changes / asymmetry</td></tr><tr><td>Motor / trophic</td><td>Reduced range of motion; motor dysfunction (weakness, tremor, dystonia); trophic changes (hair, nail, skin)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pathophysiology (proposed, multifactorial)</div><table style=\"margin:0\"><tr><th>Mechanism</th></tr><tr><td>Peripheral and central sensitisation</td></tr><tr><td>Sympathetic&ndash;afferent coupling (the \"sympathetically maintained\" model is now understood as only one contributing mechanism, not universal)</td></tr><tr><td>Neurogenic inflammation (substance P and CGRP-mediated vasodilation / plasma extravasation)</td></tr><tr><td>Central maladaptive cortical reorganisation</td></tr><tr><td>Autoimmune / inflammatory contribution (autoantibodies found in some patients)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Investigations</div><table style=\"margin:0\"><tr><th>Modality</th></tr><tr><td>Largely a clinical diagnosis (Budapest criteria)</td></tr><tr><td>Plain X-ray &mdash; patchy osteopenia (later disease)</td></tr><tr><td>Triple-phase bone scan &mdash; increased delayed-phase uptake (more sensitive, earlier changes)</td></tr><tr><td>Thermography / temperature measurement &mdash; supports vasomotor asymmetry</td></tr><tr><td>MRI &mdash; may show soft tissue and bone marrow oedema</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management (multidisciplinary)</div><table style=\"margin:0\"><tr><th>Domain</th><th>Approaches</th></tr><tr><td>Physical / functional</td><td>Graded motor imagery, mirror therapy; physiotherapy (graded exposure, desensitisation); occupational therapy</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents (gabapentinoids, TCAs); bisphosphonates (bone-related pain); corticosteroids (useful if an inflammatory / \"warm\" phase predominates); vitamin C (evidence for prophylactic use after wrist fracture / surgery to reduce CRPS incidence)</td></tr><tr><td>Interventional (refractory cases)</td><td>Sympathetic blocks (stellate ganglion for upper limb, lumbar sympathetic for lower limb) &mdash; diagnostic and sometimes therapeutic; spinal cord stimulation; intravenous regional (Bier) blocks &mdash; limited evidence</td></tr><tr><td>Psychological</td><td>CBT and pain management programmes &mdash; addressing fear-avoidance, catastrophising, and functional impact</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Prognosis</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Highly variable; many cases improve over time, especially with early, aggressive multidisciplinary management, but some progress to a chronic, disabling course</td></tr><tr><td>Early diagnosis and functional rehabilitation are associated with better outcomes</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_triamcinolone_hpa_suppression_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":87,"stem":"Regarding suppression of the hypothalamic–pituitary–adrenal (HPA) axis following intra-articular triamcinolone injection:","choices":["Suppression is maximal for 2 days","Suppression lasts longer than with dexamethasone","Suppression is shorter than with methylprednisolone","Suppression can last for up to 2 weeks or more","Suppression is greater with injection of multiple joints"],"correct":[false,true,false,true,true],"explanation":"<p>Intra-articular corticosteroid injections, though given locally, can be absorbed systemically in amounts sufficient to suppress the HPA axis. The degree and duration of suppression vary with the corticosteroid used, the dose, and the number of injection sites.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; HPA axis suppression after intra-articular triamcinolone (Kenalog) is not limited to a maximum of 2 days &mdash; triamcinolone is a relatively long-acting, depot-forming corticosteroid.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; As a depot (crystalline, poorly soluble) preparation with a long local residence time, triamcinolone produces more prolonged HPA axis suppression than dexamethasone, which is more soluble and has a shorter local duration of action despite its high potency.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> &mdash; Triamcinolone''s HPA suppression is generally considered <strong>longer</strong> than (not shorter than) that seen with methylprednisolone, reflecting its particularly prolonged depot effect at the injection site.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Suppression can persist for up to several weeks (commonly cited as up to 2 weeks or longer), reflecting slow systemic absorption from the depot at the injection site.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; Systemic absorption and the resulting HPA suppression are dose-dependent, so injecting multiple joints in one session (increasing the total corticosteroid dose) increases systemic exposure and the degree and duration of HPA axis suppression.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Corticosteroids in chronic pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Knowledge summary &mdash; corticosteroids used in pain medicine</div><table style=\"margin:0\"><tr><th>Feature</th><th>Triamcinolone (Kenalog&reg;)</th><th>Methylprednisolone (Depo-Medrone&reg;)</th><th>Dexamethasone (various brands)</th></tr><tr><td>Generic name</td><td>Triamcinolone acetonide</td><td>Methylprednisolone acetate</td><td>Dexamethasone (sodium phosphate)</td></tr><tr><td>Formulation</td><td>Crystalline suspension (depot)</td><td>Crystalline suspension (depot)</td><td>Soluble solution</td></tr><tr><td>Solubility</td><td>Poorly soluble</td><td>Poorly soluble</td><td>Highly soluble</td></tr><tr><td>Duration of local action</td><td>Long (depot effect)</td><td>Long, but shorter than triamcinolone</td><td>Short (rapidly absorbed / cleared from the injection site)</td></tr><tr><td>HPA axis suppression</td><td>Most prolonged (can last weeks)</td><td>Intermediate &mdash; shorter than triamcinolone</td><td>Shortest duration of suppression</td></tr><tr><td>Relative glucocorticoid potency (mg-for-mg)</td><td>Higher potency than methylprednisolone</td><td>Moderate&ndash;high potency</td><td>Very high potency (used at much lower doses due to solubility / short local residence)</td></tr><tr><td>Mineralocorticoid activity</td><td>Minimal</td><td>Minimal</td><td>Negligible</td></tr><tr><td>Common pain-medicine uses</td><td>Epidural, intra-articular, soft tissue injections</td><td>Epidural, intra-articular, soft tissue injections</td><td>Epidural injections (increasingly favoured for transforaminal epidurals)</td></tr><tr><td>Particulate vs non-particulate</td><td>Particulate</td><td>Particulate</td><td>Non-particulate</td></tr><tr><td>Key safety consideration</td><td>Particulate &mdash; risk of vascular occlusion / embolic infarction if inadvertently injected intravascularly (especially intra-arterially) during transforaminal epidural</td><td>Particulate &mdash; same risk as triamcinolone</td><td>Non-particulate &mdash; preferred for cervical and lumbar transforaminal epidural injections</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_low_back_pain_epidemiology_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":88,"stem":"Regarding low back pain:","choices":["Low back pain costs the UK economy approximately £2 billion per year","The lifetime prevalence of low back pain is approximately 50%","Low back pain is the leading cause of years lived with disability globally","Low back pain is more prevalent in men than women","Most acute episodes of non-specific low back pain resolve within 3 months"],"correct":[false,false,true,false,true],"explanation":"<p>Low back pain is one of the most common musculoskeletal complaints worldwide, representing both a major public health burden in terms of disability and a substantial economic cost &mdash; figures relevant to health service planning and resource allocation.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; Low back pain is estimated to cost the UK economy approximately &pound;5 billion per year, of which more than &pound;481 million is direct cost to the NHS; the remainder is indirect cost (lost productivity, work absence, disability payments).</p>\n<p style=\"margin-top:12px\"><strong>B. FALSE</strong> &mdash; The lifetime prevalence of low back pain is around 60&ndash;80%, reflecting that a large proportion of people will experience it at some point in their lives.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; Low back pain is consistently identified as the leading global cause of years lived with disability (YLD) in Global Burden of Disease studies, reflecting its cumulative impact on function and quality of life across populations.</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> &mdash; Low back pain prevalence is generally reported as similar between men and women, or slightly higher in women in some studies &mdash; not higher in men.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; The large majority of acute non-specific episodes settle spontaneously within 3 months.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Back pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Chronic back pain describes pain between the lower costal margins and the gluteal folds that persists for more than 3 months.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">In the United Kingdom, up to 50 million working days are lost each year, and half a million people receive long-term State Incapacity Benefit because of back pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A vast majority of cases settle spontaneously within 3 months. About 6% of patients develop long-standing or seriously disabling back pain; this group accounts for more than 80% of the health care resources used for back pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Risk factors for transition from acute to chronic back pain</div><table style=\"margin:0\"><tr><th>Risk factor</th></tr><tr><td>Signs of nerve root involvement</td></tr><tr><td>An ongoing compensation claim</td></tr><tr><td>Long time off work</td></tr><tr><td>High levels of psychological distress and depression</td></tr><tr><td>Poor physical fitness</td></tr><tr><td>Heavy smoking</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Red flags for serious spinal pathology</div><table style=\"margin:0\"><tr><th>Red flag</th></tr><tr><td>Presentation under 20 or over 55 years</td></tr><tr><td>History of significant trauma</td></tr><tr><td>Constant, progressive, thoracic pain</td></tr><tr><td>Past history of cancer, steroid therapy, intravenous drug use, or HIV infection</td></tr><tr><td>Unexplained weight loss</td></tr><tr><td>Systemically unwell</td></tr><tr><td>Cauda equina syndrome (saddle anaesthesia, gait or sphincter disturbance)</td></tr><tr><td>Structural deformity</td></tr><tr><td>Marked restriction of lumbar flexion (&lt;5 cm)</td></tr><tr><td>Non-mechanical pain</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><button type=\"button\" class=\"nice-guideline-btn\" onclick=\"openGuidelineModal(''ng59'',''NICE NG59 &mdash; Low Back Pain &amp; Sciatica'')\">\n  <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"9\" y1=\"13\" x2=\"15\" y2=\"13\"/><line x1=\"9\" y1=\"17\" x2=\"15\" y2=\"17\"/></svg>\n  NICE NG59 &mdash; Low Back Pain &amp; Sciatica\n</button></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_s1_nerve_root_compression_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":89,"stem":"S1 nerve root compression leads to:","choices":["Loss of adductor magnus function","Loss of ankle reflex","Loss of anal sphincter tone","Loss of gastrocnemius function","Sensory loss over the lateral border of the foot"],"correct":[false,true,false,true,true],"explanation":"<p>S1 radiculopathy produces a characteristic pattern of motor, reflex, and sensory findings that distinguishes it from L4 and L5 root lesions and from cauda equina syndrome.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; Adductor magnus is innervated predominantly by the obturator nerve (L2&ndash;L4), with a small contribution from the tibial division of the sciatic nerve (L4); it is not a muscle typically affected by an isolated S1 lesion.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; Loss of the ankle (Achilles) reflex is a classic finding in S1 radiculopathy, as the reflex arc runs via the S1 (and S2) roots through the tibial nerve to gastrocnemius / soleus.</p>\n<p style=\"margin-top:12px\"><strong>C. FALSE</strong> &mdash; Loss of anal sphincter tone is a feature of cauda equina syndrome (typically S2&ndash;S4 involvement) or bilateral / multi-level sacral root compromise, not an isolated S1 radiculopathy.</p>\n<p style=\"margin-top:12px\"><strong>D. TRUE</strong> &mdash; Gastrocnemius (with soleus) is supplied via the tibial nerve from S1&ndash;S2; weak plantarflexion and difficulty standing on tiptoe are classic motor findings in S1 radiculopathy.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; S1 dermatomal sensory loss classically affects the lateral border of the foot and the sole, distinguishing it from L5 (dorsum of the foot / big toe) and L4 (medial leg / shin).</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Dermatomes of the lower limb</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"text-align:center\"><img src=\"images/dermatomes-lower-limb.png\" alt=\"Dermatome map of the lower limb, anterior and posterior views, with territories labelled T10&ndash;T12, L1&ndash;L5 and S1&ndash;S5: L1 upper thigh, L2&ndash;L3 anterior thigh, L4 medial leg and medial foot, L5 lateral leg and dorsum of foot to the great toe, S1 posterior leg, lateral border and sole of the foot, S2 posterior thigh\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_polymyalgia_rheumatica_001', 'MTF', '{"dateAdded":"2026-09-06","rotationIndex":90,"stem":"Regarding polymyalgia rheumatica (PMR):","choices":["Typically shows no response to oral corticosteroids","Morning stiffness is a characteristic feature","Presents with shoulder and pelvic girdle pain","ESR is typically normal","Predominantly affects patients over 50 years of age"],"correct":[false,true,true,false,true],"explanation":"<p>Polymyalgia rheumatica is an inflammatory condition of older adults, characterised by proximal girdle pain and stiffness with a strong, rapid response to corticosteroids that is itself a key diagnostic and confirmatory feature.</p>\n<p style=\"margin-top:12px\"><strong>A. FALSE</strong> &mdash; PMR is characterised by a rapid and dramatic response to oral corticosteroids (typically low-dose prednisolone), often within days; this response is considered near-diagnostic, and a lack of response should prompt reconsideration of the diagnosis.</p>\n<p style=\"margin-top:12px\"><strong>B. TRUE</strong> &mdash; Morning stiffness, typically lasting more than 45 minutes to an hour and affecting the shoulder and pelvic girdles, is a hallmark clinical feature of PMR.</p>\n<p style=\"margin-top:12px\"><strong>C. TRUE</strong> &mdash; PMR classically presents with bilateral shoulder and pelvic (hip) girdle pain and stiffness, often with associated systemic symptoms (malaise, low-grade fever, weight loss).</p>\n<p style=\"margin-top:12px\"><strong>D. FALSE</strong> &mdash; ESR is typically markedly raised in PMR (frequently &gt;40 mm/hr), reflecting the underlying systemic inflammatory process; a normal ESR is atypical and should prompt consideration of alternative diagnoses, though a small proportion of cases have a normal ESR / CRP at presentation.</p>\n<p style=\"margin-top:12px\"><strong>E. TRUE</strong> &mdash; PMR predominantly affects patients over the age of 50, with incidence increasing with age; it is rare in younger patients, in whom the diagnosis should be questioned.</p>\n<div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Polymyalgia Rheumatica</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">An inflammatory rheumatic condition of unknown aetiology, causing pain and stiffness predominantly of the shoulder and pelvic girdles, occurring almost exclusively in older adults.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Predominantly affects patients over 50, with incidence rising with age (peak 70&ndash;80 years)</td></tr><tr><td>More common in women (roughly 2&ndash;3&times;)</td></tr><tr><td>More common in people of Northern European descent</td></tr><tr><td>Closely associated with giant cell arteritis (GCA) &mdash; up to 20% of PMR patients have or develop GCA; conversely, ~40&ndash;50% of GCA patients have PMR features</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features</div><table style=\"margin:0\"><tr><th>Feature</th></tr><tr><td>Bilateral shoulder girdle pain / stiffness (most common presenting feature)</td></tr><tr><td>Bilateral pelvic (hip) girdle pain / stiffness</td></tr><tr><td>Morning stiffness &mdash; characteristically prolonged, typically &gt;45 minutes</td></tr><tr><td>Systemic symptoms: malaise, low-grade fever, weight loss, low mood</td></tr><tr><td>Symptoms worse in the morning and after inactivity, easing with movement through the day</td></tr><tr><td>Peripheral synovitis / mild distal joint swelling (e.g. wrists, hands) can occur but is not the dominant feature</td></tr><tr><td>Muscle weakness is NOT a true feature &mdash; despite pain, formal strength testing should be preserved (weakness suggests an alternative diagnosis such as myositis)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Investigations</div><table style=\"margin:0\"><tr><th>Investigation</th></tr><tr><td>ESR and CRP &mdash; typically markedly raised (a minority of cases have normal inflammatory markers at presentation)</td></tr><tr><td>FBC &mdash; may show normocytic anaemia of chronic disease</td></tr><tr><td>CK (creatine kinase) &mdash; should be normal in PMR (a raised CK suggests myopathy / myositis)</td></tr><tr><td>Rule out mimics: rheumatoid factor / anti-CCP (RA), TFTs (hypothyroidism), myeloma screen if atypical features</td></tr><tr><td>Ultrasound / MRI &mdash; may show subacromial / subdeltoid bursitis, biceps tenosynovitis (supportive, not required for diagnosis)</td></tr><tr><td>Diagnosis is largely clinical, supported by inflammatory markers and response to treatment</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Screening for giant cell arteritis (GCA)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Given the strong association, all PMR patients should be asked specifically about:</p><table style=\"margin:0\"><tr><th>Feature</th></tr><tr><td>New or different headache</td></tr><tr><td>Jaw or tongue claudication</td></tr><tr><td>Scalp tenderness</td></tr><tr><td>Visual disturbance (amaurosis fugax, diplopia, vision loss)</td></tr><tr><td>Temporal artery tenderness or reduced pulsation</td></tr></table><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Any of these features warrants urgent assessment and treatment for GCA (high-dose steroids, temporal artery biopsy / ultrasound) given the risk of irreversible visual loss if untreated.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Element</th></tr><tr><td>First-line: oral corticosteroids (typically prednisolone 12.5&ndash;25 mg/day depending on severity), with gradual tapering over 1&ndash;2 years</td></tr><tr><td>Bone protection (bisphosphonates, calcium / vitamin D) given the prolonged steroid course</td></tr><tr><td>Steroid-sparing agents (e.g. methotrexate) in relapsing or difficult-to-taper cases</td></tr><tr><td>Monitor ESR / CRP alongside clinical response during tapering</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Prognosis</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Most patients require treatment for 1&ndash;2 years, with relapse common during tapering</td></tr><tr><td>Generally good prognosis with appropriate treatment, though some patients require longer-term low-dose steroids</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

